insert into public.services (tenant_id, slug, title, blurb, status, is_teaser, sort_order, short_title) values
  ('00000000-0000-0000-0000-0000000000b1', 'branding', '{"en":"Branding","ar":"الهوية البصرية"}'::jsonb, '{"en":"Identity systems that make brands unmistakable.","ar":"أنظمة هوية تجعل العلامة لا تُخطئها العين."}'::jsonb, 'published', false, 1, default),
  ('00000000-0000-0000-0000-0000000000b1', 'animations', '{"en":"Animation","ar":"الرسوم المتحركة"}'::jsonb, '{"en":"Characters and stories brought to life.","ar":"شخصيات وقصص تنبض بالحياة."}'::jsonb, 'published', false, 2, default),
  ('00000000-0000-0000-0000-0000000000b1', 'motion-graphics', '{"en":"Motion Graphics","ar":"الموشن جرافيك"}'::jsonb, '{"en":"Design in motion, for screens of every size.","ar":"تصميم متحرّك لكل مقاس شاشة."}'::jsonb, 'published', false, 3, default),
  ('00000000-0000-0000-0000-0000000000b1', 'videography', '{"en":"Videography","ar":"الإنتاج المرئي"}'::jsonb, '{"en":"Cinematic production, end to end.","ar":"إنتاج سينمائي من الفكرة إلى التسليم."}'::jsonb, 'published', false, 4, default),
  ('00000000-0000-0000-0000-0000000000b1', 'photography', '{"en":"Photography","ar":"التصوير الفوتوغرافي"}'::jsonb, '{"en":"Images that sell the moment.","ar":"صور تبيع اللحظة."}'::jsonb, 'published', false, 5, default),
  ('00000000-0000-0000-0000-0000000000b1', 'montage', '{"en":"Montage","ar":"المونتاج"}'::jsonb, '{"en":"Editing that gives footage its rhythm.","ar":"مونتاج يمنح اللقطات إيقاعها."}'::jsonb, 'published', false, 6, default),
  ('00000000-0000-0000-0000-0000000000b1', 'event-planning', '{"en":"Event Planning","ar":"تنظيم الفعاليات"}'::jsonb, '{"en":"Experiences planned down to the detail.","ar":"تجارب مخططة حتى آخر تفصيل."}'::jsonb, 'published', false, 7, default),
  ('00000000-0000-0000-0000-0000000000b1', 'advertising', '{"en":"Advertising","ar":"الإعلان"}'::jsonb, '{"en":"Campaigns that move audiences.","ar":"حملات تحرّك الجمهور."}'::jsonb, 'published', false, 8, default),
  ('00000000-0000-0000-0000-0000000000b1', 'social-media', '{"en":"Social Media","ar":"السوشيال ميديا"}'::jsonb, '{"en":"Always-on presence that converts.","ar":"حضور دائم يتحوّل إلى نتائج."}'::jsonb, 'published', false, 9, default),
  ('00000000-0000-0000-0000-0000000000b1', 'web-development', '{"en":"Web Development","ar":"تطوير المواقع"}'::jsonb, '{"en":"Fast, secure, accessible sites.","ar":"مواقع سريعة وآمنة وسهلة الوصول."}'::jsonb, 'published', false, 10, default),
  ('00000000-0000-0000-0000-0000000000b1', 'seo-geo-aeo', '{"en":"SEO / GEO / AEO","ar":"تحسين الظهور SEO / GEO / AEO"}'::jsonb, '{"en":"Be found by people and by AI answer engines.","ar":"أن تُوجد أمام الناس وأمام محركات الإجابة."}'::jsonb, 'published', false, 11, '{"en":"SEO / GEO / AEO","ar":"تحسين الظهور"}'::jsonb),
  ('00000000-0000-0000-0000-0000000000b1', 'music', '{"en":"Music","ar":"الموسيقى"}'::jsonb, '{"en":"Original sound and scoring.","ar":"موسيقى أصلية وتوزيع صوتي."}'::jsonb, 'published', false, 12, default),
  ('00000000-0000-0000-0000-0000000000b1', 'merchandise', '{"en":"Merchandise","ar":"المنتجات الترويجية"}'::jsonb, '{"en":"Branded products people actually keep.","ar":"منتجات بعلامتك يحتفظ بها الناس."}'::jsonb, 'published', false, 13, default),
  ('00000000-0000-0000-0000-0000000000b1', 'gaming', '{"en":"Gaming","ar":"الألعاب"}'::jsonb, '{"en":"Worlds, assets, and in-game brand work.","ar":"عوالم وأصول وحضور داخل اللعبة."}'::jsonb, 'published', true, 14, default)
