  ('00000000-0000-0000-0000-0000000000b1', 'fintech-product-film', '{"en":"Fintech Product Film","ar":"فيلم منتج لشركة تقنية مالية"}'::jsonb, '{"en":"Scriptwriting, cinematic production, and a 60-second cutdown for paid media.","ar":"كتابة سيناريو، وإنتاج سينمائي، ونسخة 60 ثانية للإعلانات المدفوعة."}'::jsonb, 'archived', true, 3)
