  ('00000000-0000-0000-0000-0000000000b1', '5eed0a00-0000-4000-8000-000000000024', 'image', 'static', 'stills/project/g16.jpg', 'image/jpeg', 1600, 900, 'stills', '{showreel}', '{"en":"Silhouetted arms reaching through swirling orange dust and flying particles.","ar":"ظل ذراعين تمتدان عبر غبار برتقالي متطاير وجزيئات متناثرة."}'::jsonb),
  ('00000000-0000-0000-0000-0000000000b1', '5eed0a00-0000-4000-8000-000000000025', 'image', 'static', 'stills/project/g17.jpg', 'image/jpeg', 1600, 900, 'stills', '{showreel}', '{"en":"A bright white sun glowing through thick orange haze.","ar":"شمس بيضاء ساطعة تتوهج عبر ضباب برتقالي كثيف."}'::jsonb),
  ('00000000-0000-0000-0000-0000000000b1', '5eed0a00-0000-4000-8000-000000000026', 'image', 'static', 'stills/project/g18.jpg', 'image/jpeg', 1600, 900, 'stills', '{showreel}', '{"en":"A woman in a floral dress holding a glowing white sphere against black.","ar":"امرأة بفستان مزهّر تحمل كرة بيضاء مضيئة على خلفية سوداء."}'::jsonb),
  ('00000000-0000-0000-0000-0000000000b1', '5eed0a00-0000-4000-8000-000000000027', 'image', 'static', 'stills/project/s1.jpg', 'image/jpeg', 1200, 676, 'stills', '{showreel}', '{"en":"Line sketch of a masked person wearing ski goggles.","ar":"رسمة خطية لشخص ملثّم يرتدي نظارة تزلج."}'::jsonb),
  ('00000000-0000-0000-0000-0000000000b1', '5eed0a00-0000-4000-8000-000000000028', 'image', 'static', 'stills/project/s2.jpg', 'image/jpeg', 1200, 676, 'stills', '{showreel}', '{"en":"Line sketch of a hand turning an oven knob beside a digital clock.","ar":"رسمة خطية ليد تدير مقبض فرن بجانب ساعة رقمية."}'::jsonb),
  ('00000000-0000-0000-0000-0000000000b1', '5eed0a00-0000-4000-8000-000000000029', 'image', 'static', 'stills/project/s3.jpg', 'image/jpeg', 1200, 676, 'stills', '{showreel}', '{"en":"Line sketch of a hand writing in a notebook with a pen.","ar":"رسمة خطية ليد تكتب في دفتر بقلم."}'::jsonb),
