insert into public.portfolio (tenant_id, slug, title, project_type, teaser, summary, sector_id, client_id, year, is_featured, poster_media_id, preview_video_path, preview_start_s, preview_end_s, lead, goal, result, scope, keywords, results, status, is_placeholder, sort_order) values
  ('00000000-0000-0000-0000-0000000000b1', 'the-rider', '{"en":"The Rider","ar":"الراكب"}'::jsonb, '{"en":"Brand film","ar":"فيلم للعلامة"}'::jsonb, '{"en":"A launch film shot in the desert at first light.","ar":"فيلم إطلاق صُوّر في الصحراء مع أول ضوء."}'::jsonb, '{"en":"The brief was to introduce a new model to a region that has seen every car ad already. We skipped the studio and the showroom and went to the desert at 5am, with one rider, one vehicle, and a crew of twelve.","ar":"كان البريف تقديم موديل جديد لمنطقة شافت كل إعلانات السيارات. تركنا الاستوديو والمعرض ورحنا للصحراء الساعة خمسة الفجر، براكب واحد ومركبة واحدة وفريق من اثني عشر شخص."}'::jsonb, (select id from public.sectors where tenant_id = '00000000-0000-0000-0000-0000000000b1' and slug = 'automotive'), (select id from public.clients where tenant_id = '00000000-0000-0000-0000-0000000000b1' and slug = 'client-a'), 2026, true, '5eed0a00-0000-4000-8000-000000000001', '/media/showreel.mp4', 1, 3.7, '{"en":"A launch film built around one image: a rider who looks like the landscape made him.","ar":"فيلم إطلاق مبني حول صورة واحدة: راكب يبدو وكأن الأرض هي اللي صنعته."}'::jsonb, '{"en":"Make a launch people would stop scrolling for, and remember the model name the next day.","ar":"إطلاق يوقّف الناس عن التمرير، ويخليهم يتذكرون اسم الموديل اليوم اللي بعده."}'::jsonb, '{"en":"The film ran across broadcast, cinema and social, with cutdowns tailored to each placement.","ar":"عُرض الفيلم على التلفزيون والسينما والسوشيال ميديا، مع نسخ قصيرة مفصّلة لكل منصة."}'::jsonb, '[{"en":"Creative concept","ar":"الفكرة الإبداعية"},{"en":"Storyboard and art direction","ar":"الستوريبورد والإخراج الفني"},{"en":"Production and filming","ar":"الإنتاج والتصوير"},{"en":"Edit, grade and sound design","ar":"المونتاج والتلوين وتصميم الصوت"},{"en":"Cutdowns for social","ar":"نسخ قصيرة للسوشيال ميديا"}]'::jsonb, '[{"en":"Brand film","ar":"فيلم للعلامة"},{"en":"Launch","ar":"إطلاق"},{"en":"Desert shoot","ar":"تصوير صحراوي"},{"en":"Art direction","ar":"إخراج فني"}]'::jsonb, '[{"value":"XXM","label":{"en":"Views across platforms","ar":"مشاهدة على المنصات"}},{"value":"+XX%","label":{"en":"Brand recall after launch","ar":"تذكّر العلامة بعد الإطلاق"}}]'::jsonb, 'published', true, 1),
  ('00000000-0000-0000-0000-0000000000b1', 'kitchen-hours', '{"en":"Kitchen Hours","ar":"ساعات المطبخ"}'::jsonb, '{"en":"Product campaign","ar":"حملة منتج"}'::jsonb, '{"en":"A campaign built around the ten minutes before dinner.","ar":"حملة مبنية حول العشر دقائق قبل العشاء."}'::jsonb, '{"en":"We turned a product launch into a series of small, true moments: the oven timer, the first taste, the table filling up.","ar":"حوّلنا إطلاق منتج لسلسلة لحظات صغيرة وحقيقية: مؤقت الفرن، أول تذوّق، والسفرة وهي تمتلي."}'::jsonb, (select id from public.sectors where tenant_id = '00000000-0000-0000-0000-0000000000b1' and slug = 'food-and-beverage'), (select id from public.clients where tenant_id = '00000000-0000-0000-0000-0000000000b1' and slug = 'client-b'), 2026, true, '5eed0a00-0000-4000-8000-000000000002', '/media/showreel.mp4', 4.1, 5.4, '{"en":"A campaign about the ten minutes before dinner, when the kitchen is the busiest room in the house.","ar":"حملة عن العشر دقائق قبل العشاء، لما يكون المطبخ أكثر غرفة زحمة في البيت."}'::jsonb, '{"en":"Put the product in real homes, not on a set.","ar":"نحط المنتج في بيوت حقيقية، مو في استوديو."}'::jsonb, '{"en":"A film, a stills library and a month of social content from one production.","ar":"فيلم ومكتبة صور وشهر من محتوى السوشيال ميديا من إنتاج واحد."}'::jsonb, '[{"en":"Campaign strategy","ar":"استراتيجية الحملة"},{"en":"Product film","ar":"فيلم المنتج"},{"en":"Photography","ar":"التصوير الفوتوغرافي"},{"en":"Social content","ar":"محتوى السوشيال ميديا"}]'::jsonb, '[{"en":"Campaign","ar":"حملة"},{"en":"Product film","ar":"فيلم منتج"},{"en":"Social","ar":"سوشيال ميديا"}]'::jsonb, '[{"value":"XX","label":{"en":"Pieces of content from one shoot","ar":"قطعة محتوى من تصوير واحد"}},{"value":"+XX%","label":{"en":"Engagement against the last campaign","ar":"تفاعل مقارنة بالحملة السابقة"}}]'::jsonb, 'published', true, 2),
  ('00000000-0000-0000-0000-0000000000b1', 'notebook', '{"en":"Notebook","ar":"الدفتر"}'::jsonb, '{"en":"Rebrand","ar":"إعادة بناء هوية"}'::jsonb, '{"en":"A rebrand that started, literally, on paper.","ar":"هوية جديدة بدأت حرفياً على الورق."}'::jsonb, '{"en":"Every direction started as a pencil sketch before it touched a screen, so the final system still feels drawn by hand.","ar":"كل اتجاه بدأ برسمة بالقلم قبل ما يوصل للشاشة، عشان النظام النهائي يبقى وكأنه مرسوم باليد."}'::jsonb, (select id from public.sectors where tenant_id = '00000000-0000-0000-0000-0000000000b1' and slug = 'education'), (select id from public.clients where tenant_id = '00000000-0000-0000-0000-0000000000b1' and slug = 'client-c'), 2025, true, '5eed0a00-0000-4000-8000-000000000003', '/media/showreel.mp4', 6.2, 7.9, '{"en":"A rebrand that kept what people loved and fixed what nobody could read.","ar":"هوية جديدة حافظت على اللي يحبه الناس، وصلّحت اللي ما أحد كان يقدر يقرأه."}'::jsonb, '{"en":"One identity that works as well on a notebook as on a building.","ar":"هوية واحدة تشتغل على الدفتر زي ما تشتغل على المبنى."}'::jsonb, '{"en":"A full identity system, rolled out across every campus.","ar":"نظام هوية كامل، طُبّق في كل الفروع."}'::jsonb, '[{"en":"Brand strategy","ar":"استراتيجية العلامة"},{"en":"Logo and type system","ar":"الشعار ونظام الخطوط"},{"en":"Arabic and English lettering","ar":"الخط العربي والإنجليزي"},{"en":"Brand guidelines","ar":"دليل الهوية"}]'::jsonb, '[{"en":"Identity","ar":"هوية"},{"en":"Rebrand","ar":"إعادة بناء"},{"en":"Guidelines","ar":"دليل الاستخدام"}]'::jsonb, '[{"value":"XX","label":{"en":"Touchpoints redesigned","ar":"نقطة تواصل أُعيد تصميمها"}},{"value":"XX","label":{"en":"Weeks from brief to launch","ar":"أسبوع من البريف للإطلاق"}}]'::jsonb, 'published', true, 3),
  ('00000000-0000-0000-0000-0000000000b1', 'ink', '{"en":"Ink","ar":"حبر"}'::jsonb, '{"en":"Title sequence","ar":"تتر افتتاحي"}'::jsonb, '{"en":"Title sequence and motion system for a cultural season.","ar":"تتر افتتاحي ونظام موشن لموسم ثقافي."}'::jsonb, '{"en":"We filmed ink, pen strokes and a human eye at extreme close range, then built a motion system from the same footage.","ar":"صوّرنا الحبر وحركة القلم وعين إنسان من مسافة قريبة جداً، وبنينا نظام موشن من نفس اللقطات."}'::jsonb, (select id from public.sectors where tenant_id = '00000000-0000-0000-0000-0000000000b1' and slug = 'culture'), (select id from public.clients where tenant_id = '00000000-0000-0000-0000-0000000000b1' and slug = 'client-d'), 2025, true, '5eed0a00-0000-4000-8000-000000000004', '/media/showreel.mp4', 12, 13, '{"en":"A title sequence shot in macro, where ink behaves like a landscape.","ar":"تتر افتتاحي مصوّر بالماكرو، الحبر فيه يتصرف كأنه أرض."}'::jsonb, '{"en":"An opening that sets the tone for a whole season in forty seconds.","ar":"افتتاحية تحدد نبرة موسم كامل في أربعين ثانية."}'::jsonb, '{"en":"A sequence and a motion kit reused across every event of the season.","ar":"تتر وحزمة موشن استُخدمت في كل فعاليات الموسم."}'::jsonb, '[{"en":"Title design","ar":"تصميم التتر"},{"en":"Macro filming","ar":"تصوير ماكرو"},{"en":"Motion system","ar":"نظام الموشن"},{"en":"Original score","ar":"موسيقى أصلية"}]'::jsonb, '[{"en":"Motion","ar":"موشن"},{"en":"Title design","ar":"تصميم التتر"},{"en":"Macro filming","ar":"تصوير ماكرو"}]'::jsonb, '[{"value":"XX","label":{"en":"Events using the motion kit","ar":"فعالية استخدمت حزمة الموشن"}},{"value":"0:40","label":{"en":"Seconds of opening title","ar":"ثانية من التتر الافتتاحي"}}]'::jsonb, 'published', true, 4),
  ('00000000-0000-0000-0000-0000000000b1', 'terrain', '{"en":"Terrain","ar":"تضاريس"}'::jsonb, '{"en":"Launch photography","ar":"تصوير إطلاق"}'::jsonb, '{"en":"Material studies for a real estate launch.","ar":"دراسات خامات لإطلاق مشروع عقاري."}'::jsonb, '{"en":"Before there was a building to photograph, we photographed what it would be made of.","ar":"قبل ما يكون فيه مبنى نصوّره، صوّرنا الأشياء اللي بيتبنى منها."}'::jsonb, (select id from public.sectors where tenant_id = '00000000-0000-0000-0000-0000000000b1' and slug = 'real-estate'), (select id from public.clients where tenant_id = '00000000-0000-0000-0000-0000000000b1' and slug = 'client-e'), 2025, true, '5eed0a00-0000-4000-8000-000000000005', '/media/showreel.mp4', 13, 13.9, '{"en":"A launch told through the materials the project is built from.","ar":"إطلاق يُحكى من خلال الخامات اللي المشروع مبني منها."}'::jsonb, '{"en":"Sell a place that didn''t exist yet.","ar":"نسوّق لمكان ما كان موجود للحين."}'::jsonb, '{"en":"A photography library used across the launch and the sales centre.","ar":"مكتبة صور استُخدمت في الإطلاق ومركز المبيعات."}'::jsonb, '[{"en":"Art direction","ar":"الإخراج الفني"},{"en":"Still life photography","ar":"تصوير الطبيعة الصامتة"},{"en":"Launch campaign","ar":"حملة الإطلاق"}]'::jsonb, '[{"en":"Photography","ar":"تصوير فوتوغرافي"},{"en":"Materials","ar":"الخامات"},{"en":"Launch","ar":"إطلاق"}]'::jsonb, '[{"value":"XX","label":{"en":"Images delivered","ar":"صورة مسلّمة"}},{"value":"XX","label":{"en":"Placements in the launch","ar":"موقع ظهرت فيه في الإطلاق"}}]'::jsonb, 'published', true, 5),
  ('00000000-0000-0000-0000-0000000000b1', 'first-light', '{"en":"First Light","ar":"أول ضوء"}'::jsonb, '{"en":"Live event","ar":"فعالية حيّة"}'::jsonb, '{"en":"Opening night visuals for a live event.","ar":"مرئيات ليلة الافتتاح لفعالية حيّة."}'::jsonb, '{"en":"We designed the stage visuals, the opening film and the moment the whole venue went dark before the first light came up.","ar":"صمّمنا مرئيات المسرح والفيلم الافتتاحي واللحظة اللي أظلم فيها المكان كله قبل ما يطلع أول ضوء."}'::jsonb, (select id from public.sectors where tenant_id = '00000000-0000-0000-0000-0000000000b1' and slug = 'entertainment'), (select id from public.clients where tenant_id = '00000000-0000-0000-0000-0000000000b1' and slug = 'client-f'), 2024, true, '5eed0a00-0000-4000-8000-000000000006', '/media/showreel.mp4', 15.9, 17.3, '{"en":"An opening night where the light itself was the headline act.","ar":"ليلة افتتاح كان الضوء نفسه فيها هو العرض الرئيسي."}'::jsonb, '{"en":"One moment everyone in the room would film.","ar":"لحظة وحدة كل اللي في القاعة يصوّرونها."}'::jsonb, '{"en":"An opening that ran on every guest''s phone before it ran on the news.","ar":"افتتاحية انتشرت على جوالات الحضور قبل ما تنعرض في الأخبار."}'::jsonb, '[{"en":"Show concept","ar":"فكرة العرض"},{"en":"Stage visuals","ar":"مرئيات المسرح"},{"en":"Opening film","ar":"الفيلم الافتتاحي"},{"en":"Event production","ar":"إنتاج الفعالية"}]'::jsonb, '[{"en":"Live event","ar":"فعالية حيّة"},{"en":"Stage visuals","ar":"مرئيات المسرح"},{"en":"Show design","ar":"تصميم العرض"}]'::jsonb, '[{"value":"XXK","label":{"en":"Guests on opening night","ar":"ضيف في ليلة الافتتاح"}},{"value":"XXM","label":{"en":"Social views in the first week","ar":"مشاهدة في الأسبوع الأول"}}]'::jsonb, 'published', true, 6),
  ('00000000-0000-0000-0000-0000000000b1', 'dust-trail', '{"en":"Dust Trail","ar":"أثر الغبار"}'::jsonb, '{"en":"Social series","ar":"سلسلة سوشيال"}'::jsonb, '{"en":"A twelve-part social series cut from one desert shoot.","ar":"سلسلة من اثني عشر جزء للسوشيال من تصوير صحراوي واحد."}'::jsonb, '{"en":"A twelve-part social series cut from one desert shoot.","ar":"سلسلة من اثني عشر جزء للسوشيال من تصوير صحراوي واحد."}'::jsonb, (select id from public.sectors where tenant_id = '00000000-0000-0000-0000-0000000000b1' and slug = 'automotive'), (select id from public.clients where tenant_id = '00000000-0000-0000-0000-0000000000b1' and slug = 'client-a'), 2025, false, '5eed0a00-0000-4000-8000-000000000023', '/media/showreel.mp4', 15, 15.8, default, default, default, default, default, default, 'published', true, 7),
