insert into public.testimonials (tenant_id, slug, quote, author_name, author_role, placements, status, is_placeholder, sort_order, consent_obtained_at, consent_reference, client_id, portfolio_id) values
  ('00000000-0000-0000-0000-0000000000b1', 'quote-home-1', '{"en":"They asked better questions about our business in the first meeting than our last agency did in a year. The work showed it.","ar":"سألونا أسئلة عن شغلنا في أول اجتماع أعمق مما سألته وكالتنا السابقة في سنة كاملة. وهذا بان في النتيجة."}'::jsonb, '{"en":"Client name","ar":"اسم العميل"}'::jsonb, '{"en":"Marketing Director, Company","ar":"مدير التسويق، الشركة"}'::jsonb, '{home,work}', 'published', true, 1, now(), 'PLACEHOLDER demo, not a real quote', default, default),
  ('00000000-0000-0000-0000-0000000000b1', 'quote-home-2', '{"en":"One team for the identity, the film, and the launch event. Nothing got lost between vendors because there weren''t any.","ar":"فريق واحد للهوية والفيلم وفعالية الإطلاق. ما ضاع شيء بين الجهات لأنه ما كان فيه جهات أصلاً."}'::jsonb, '{"en":"Client name","ar":"اسم العميل"}'::jsonb, '{"en":"Head of Brand, Company","ar":"رئيس العلامة التجارية، الشركة"}'::jsonb, '{home,work}', 'published', true, 2, now(), 'PLACEHOLDER demo, not a real quote', default, default),
  ('00000000-0000-0000-0000-0000000000b1', 'quote-home-3', '{"en":"The Arabic was written, not translated. Our audience noticed before we told them.","ar":"العربي كان مكتوباً، مو مترجماً. جمهورنا لاحظ قبل ما نقول لهم."}'::jsonb, '{"en":"Client name","ar":"اسم العميل"}'::jsonb, '{"en":"CEO, Company","ar":"الرئيس التنفيذي، الشركة"}'::jsonb, '{home,work}', 'published', true, 3, now(), 'PLACEHOLDER demo, not a real quote', default, default),
  ('00000000-0000-0000-0000-0000000000b1', 'quote-the-rider', '{"en":"They came back with a film that felt like it was made for this region, not adapted for it. Our dealers were asking for it before it aired.","ar":"رجعوا بفيلم يحسسك أنه مصنوع لهذه المنطقة، مو معدّل لها. وكلاؤنا كانوا يطلبونه قبل ما ينعرض."}'::jsonb, '{"en":"Client name","ar":"اسم العميل"}'::jsonb, '{"en":"Marketing Director, Company","ar":"مدير التسويق، الشركة"}'::jsonb, '{}', 'published', true, 4, now(), 'PLACEHOLDER demo, not a real quote', (select id from public.clients where tenant_id = '00000000-0000-0000-0000-0000000000b1' and slug = 'client-a'), (select id from public.portfolio where tenant_id = '00000000-0000-0000-0000-0000000000b1' and slug = 'the-rider')),
  ('00000000-0000-0000-0000-0000000000b1', 'quote-kitchen-hours', '{"en":"One shoot gave us a month of content that still looked like one idea.","ar":"تصوير واحد أعطانا شهر محتوى وكلّه يبان فكرة واحدة."}'::jsonb, '{"en":"Client name","ar":"اسم العميل"}'::jsonb, '{"en":"Head of Brand, Company","ar":"رئيس العلامة التجارية، الشركة"}'::jsonb, '{}', 'published', true, 5, now(), 'PLACEHOLDER demo, not a real quote', (select id from public.clients where tenant_id = '00000000-0000-0000-0000-0000000000b1' and slug = 'client-b'), (select id from public.portfolio where tenant_id = '00000000-0000-0000-0000-0000000000b1' and slug = 'kitchen-hours')),
  ('00000000-0000-0000-0000-0000000000b1', 'quote-notebook', '{"en":"The Arabic was written, not translated. Our students noticed before we told them.","ar":"العربي كان مكتوباً، مو مترجماً. طلابنا لاحظوا قبل ما نقول لهم."}'::jsonb, '{"en":"Client name","ar":"اسم العميل"}'::jsonb, '{"en":"CEO, Company","ar":"الرئيس التنفيذي، الشركة"}'::jsonb, '{}', 'published', true, 6, now(), 'PLACEHOLDER demo, not a real quote', (select id from public.clients where tenant_id = '00000000-0000-0000-0000-0000000000b1' and slug = 'client-c'), (select id from public.portfolio where tenant_id = '00000000-0000-0000-0000-0000000000b1' and slug = 'notebook')),
  ('00000000-0000-0000-0000-0000000000b1', 'quote-ink', '{"en":"It set the tone before anyone said a word.","ar":"حدد النبرة قبل ما أحد يتكلم."}'::jsonb, '{"en":"Client name","ar":"اسم العميل"}'::jsonb, '{"en":"Programme Director, Company","ar":"مدير البرنامج، الشركة"}'::jsonb, '{}', 'published', true, 7, now(), 'PLACEHOLDER demo, not a real quote', (select id from public.clients where tenant_id = '00000000-0000-0000-0000-0000000000b1' and slug = 'client-d'), (select id from public.portfolio where tenant_id = '00000000-0000-0000-0000-0000000000b1' and slug = 'ink')),
  ('00000000-0000-0000-0000-0000000000b1', 'quote-terrain', '{"en":"They made concrete look like something you''d want to touch.","ar":"خلّوا الخرسانة تبان شيء تبي تلمسه."}'::jsonb, '{"en":"Client name","ar":"اسم العميل"}'::jsonb, '{"en":"Sales Director, Company","ar":"مدير المبيعات، الشركة"}'::jsonb, '{}', 'published', true, 8, now(), 'PLACEHOLDER demo, not a real quote', (select id from public.clients where tenant_id = '00000000-0000-0000-0000-0000000000b1' and slug = 'client-e'), (select id from public.portfolio where tenant_id = '00000000-0000-0000-0000-0000000000b1' and slug = 'terrain')),
  ('00000000-0000-0000-0000-0000000000b1', 'quote-first-light', '{"en":"The room went quiet, then everyone reached for their phones. That was the brief.","ar":"القاعة سكتت، وبعدها الكل طلّع جواله. وهذا كان البريف."}'::jsonb, '{"en":"Client name","ar":"اسم العميل"}'::jsonb, '{"en":"Event Director, Company","ar":"مدير الفعالية، الشركة"}'::jsonb, '{}', 'published', true, 9, now(), 'PLACEHOLDER demo, not a real quote', (select id from public.clients where tenant_id = '00000000-0000-0000-0000-0000000000b1' and slug = 'client-f'), (select id from public.portfolio where tenant_id = '00000000-0000-0000-0000-0000000000b1' and slug = 'first-light'))
